"use strict";
function labelNumber(value) {
    const digits = "٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹";
    const match = value
        .replace(/[٠-٩۰-۹]/g, (digit) => String(digits.indexOf(digit) % 10))
        .match(/\d+(?:\.\d+)?/);
    const number = match ? Number(match[0]) : NaN;
    return Number.isFinite(number) ? number : undefined;
}
function groupChapters(chapters) {
    const groups = new Map();
    for (const chapter of chapters ?? []) {
        const volume = chapter.volume?.trim() ?? "";
        const group = groups.get(volume) ?? { chapters: [] };
        groups.set(volume, {
            title: group.title ?? (chapter.volumeTitle?.trim() || undefined),
            chapters: [...group.chapters, chapter],
        });
    }
    return [...groups]
        .map(([volume, group]) => {
        const number = labelNumber(volume);
        const base = number === undefined ? volume || "Chapters" : `Volume ${number}`;
        return {
            volume,
            label: group.title || base,
            number,
            chapters: group.chapters,
        };
    })
        .sort((left, right) => {
        if (!left.volume)
            return 1;
        if (!right.volume)
            return -1;
        if (left.number !== undefined && right.number !== undefined)
            return left.number - right.number;
        return left.volume.localeCompare(right.volume, undefined, {
            numeric: true,
            sensitivity: "base",
        });
    });
}
function orderedChapters(selected, query, sort) {
    const term = query.trim().toLowerCase();
    const positioned = selected.length > 0 && selected.every((chapter) => chapter.position != null);
    const positionedNumbers = selected
        .map((chapter) => ({
        position: chapter.position,
        number: labelNumber(chapter.chapter ?? ""),
    }))
        .filter((chapter) => chapter.position != null && chapter.number != null)
        .sort((left, right) => left.position - right.position);
    const positionDirection = positionedNumbers.reduce((direction, chapter, index) => index ? direction + Math.sign(chapter.number - positionedNumbers[index - 1].number) : 0, 0) < 0
        ? -1
        : 1;
    const items = selected
        .map((chapter, index) => ({ chapter, index }))
        .filter(({ chapter }) => !term ||
        chapter.title.toLowerCase().includes(term) ||
        chapter.chapter?.toLowerCase().includes(term));
    items.sort((a, b) => {
        if (positioned)
            return (a.chapter.position - b.chapter.position) * positionDirection || a.index - b.index;
        const left = a.chapter.chapter ? labelNumber(a.chapter.chapter) : undefined;
        const right = b.chapter.chapter ? labelNumber(b.chapter.chapter) : undefined;
        if (left !== undefined && right !== undefined)
            return left - right || a.index - b.index;
        if (left !== undefined)
            return -1;
        if (right !== undefined)
            return 1;
        return (a.chapter.title.localeCompare(b.chapter.title, undefined, { numeric: true }) ||
            a.index - b.index);
    });
    return (sort === "newest" ? items.reverse() : items).map(({ chapter }) => chapter);
}
function information(ebook, translations) {
    const t = (key, variables = {}) => (translations?.[key] ?? key).replace(/\{([^{}]+)\}/g, (match, key) => String(variables[key] ?? match));
    const score = ebook.score == null
        ? null
        : ebook.score > 10
            ? `${(ebook.score / 10).toFixed(1)} / 10`
            : `${ebook.score.toFixed(1)} / 10`;
    const rows = [
        { label: t("Author"), value: ebook.authors.join(" · ") || t("Not available") },
        {
            label: t("First aired"),
            value: ebook.publishedAt || (ebook.year ? String(ebook.year) : t("Not available")),
        },
        { label: t("Status"), value: ebook.status || t("Not available") },
        { label: t("Genres"), value: ebook.genres.join(" · ") || t("Not available") },
        { label: t("Rating"), value: score || t("Not available") },
        ...(ebook.pages ? [{ label: t("Length"), value: t("{n} pages", { n: ebook.pages }) }] : []),
        ...(ebook.editionCount
            ? [{ label: t("Editions"), value: t("{n} published", { n: ebook.editionCount }) }]
            : []),
        ...(ebook.readerRating
            ? [
                {
                    label: t("Readers"),
                    value: `${ebook.readerRating.toFixed(1)} / 5${ebook.readerRatingCount ? ` · ${t("{n} ratings", { n: ebook.readerRatingCount })}` : ""}`,
                },
            ]
            : []),
        ...(ebook.shelvedBy
            ? [{ label: t("Want to read"), value: t("{n} readers", { n: ebook.shelvedBy }) }]
            : []),
        ...(ebook.people?.length
            ? [{ label: t("Characters"), value: ebook.people.slice(0, 5).join(" · ") }]
            : []),
        ...(ebook.places?.length
            ? [{ label: t("Setting"), value: ebook.places.slice(0, 5).join(" · ") }]
            : []),
        ...(ebook.periods?.length
            ? [{ label: t("Period"), value: ebook.periods.slice(0, 4).join(" · ") }]
            : []),
        ...(ebook.languages?.length
            ? [{ label: t("Translations"), value: t("{n} languages", { n: ebook.languages.length }) }]
            : []),
    ];
    return rows;
}
function harborEBookDetail(text) {
    const input = JSON.parse(text);
    if (input.operation === 'information')
        return JSON.stringify(information(input.book, input.translations));
    const groups = groupChapters(input.chapters);
    if (input.operation === 'groups')
        return JSON.stringify(groups);
    const selected = groups.find(group => group.volume === input.volume)?.chapters ?? [];
    return JSON.stringify(orderedChapters(selected, input.query ?? '', input.sort ?? 'oldest'));
}
